export declare const errorBoundaryCSS = ".error-boundary-container {\n  min-height: 100vh;\n  background: linear-gradient(to bottom, #fee2e2, #fecaca);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 1rem;\n}\n\n.error-boundary-content {\n  max-width: 28rem;\n  width: 100%;\n  background: white;\n  border-radius: 0.5rem;\n  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);\n  padding: 2rem;\n  text-align: center;\n}\n\n.error-icon {\n  font-size: 4rem;\n  margin-bottom: 1rem;\n}\n\n.error-title {\n  font-size: 1.5rem;\n  font-weight: bold;\n  color: #111827;\n  margin-bottom: 0.5rem;\n}\n\n.error-message {\n  color: #4b5563;\n  margin-bottom: 1.5rem;\n}\n\n.error-details {\n  margin-bottom: 1.5rem;\n  text-align: left;\n}\n\n.error-details summary {\n  cursor: pointer;\n  font-size: 0.875rem;\n  font-weight: 500;\n  color: #374151;\n  margin-bottom: 0.5rem;\n}\n\n.error-details pre {\n  font-size: 0.75rem;\n  background: #f3f4f6;\n  padding: 0.75rem;\n  border-radius: 0.25rem;\n  overflow: auto;\n  max-height: 10rem;\n}\n\n.error-actions {\n  display: flex;\n  gap: 0.75rem;\n  justify-content: center;\n}\n\n.error-btn {\n  padding: 0.5rem 1.5rem;\n  border-radius: 0.5rem;\n  border: none;\n  cursor: pointer;\n  font-weight: 500;\n  transition: all 0.2s;\n}\n\n.error-btn-primary {\n  background: #ef4444;\n  color: white;\n}\n\n.error-btn-primary:hover {\n  background: #dc2626;\n}\n\n.error-btn-secondary {\n  background: #e5e7eb;\n  color: #1f2937;\n}\n\n.error-btn-secondary:hover {\n  background: #d1d5db;\n}\n";
